"""Original-map school marker and pedestrian measurements; no legal cutoff."""
import hashlib
import json
import math
from pathlib import Path


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def pair(value):
    if not isinstance(value, list) or len(value) != 2 or any(type(x) not in (int, float) or not math.isfinite(x) for x in value):
        raise ValueError("invalid original coordinate")
    return value


def load_site(path):
    """Reject a named school flag without two original boundary markers."""
    path = Path(path)
    site = json.loads(path.read_text())
    if (site.get("format"), site.get("cell_id"), site.get("layout"), site.get("control")) != (
        "worker-school-setting-site", "C398030", "school_zone", "school"
    ):
        raise ValueError("wrong school site identity")
    source = site.get("map_source", {})
    map_path = path.parent / source.get("path", "")
    if not map_path.is_file() or sha(map_path) != source.get("sha256"):
        raise ValueError("missing or stale original school map source")
    markers = site.get("school_boundary_markers")
    if not isinstance(markers, list) or len(markers) < 2:
        raise ValueError("original school boundary markers missing")
    for marker in markers:
        if not isinstance(marker, dict) or not marker.get("original_object_id") or "school" not in str(marker.get("name", "")).lower():
            raise ValueError("school marker is not an original identified object")
        pair(marker.get("location_xy_m"))
    start, end = sorted(m["location_xy_m"][0] for m in markers[:2])
    if not start < end:
        raise ValueError("school marker boundaries collapse")
    for name in ("ego_start_xy_m", "ego_end_xy_m", "pedestrian_start_xy_m", "pedestrian_end_xy_m"):
        pair(site.get(name))
    ex0, ex1 = site["ego_start_xy_m"][0], site["ego_end_xy_m"][0]
    px0, px1 = site["pedestrian_start_xy_m"][0], site["pedestrian_end_xy_m"][0]
    if not ex0 < start < px0 == px1 < end < ex1:
        raise ValueError("pedestrian not within original school marker boundaries")
    route = site.get("lane_route_samples")
    if (not isinstance(route, list) or len(route) < 2
            or any(not isinstance(sample, dict) for sample in route)):
        raise ValueError("original school lane route readback missing")
    if (route[0].get("center_xy_m") != site["ego_start_xy_m"]
            or route[-1].get("center_xy_m") != site["ego_end_xy_m"]
            or route[0].get("yaw_deg") != site.get("ego_spawn_yaw_deg")):
        raise ValueError("original school lane route endpoint mismatch")
    previous_x = None
    midpoint_y = pair(route[len(route) // 2].get("center_xy_m"))[1]
    for sample in route:
        center = pair(sample.get("center_xy_m"))
        x = sample.get("requested_x_m")
        yaw = sample.get("yaw_deg")
        width = sample.get("width_m")
        if (any(type(value) not in (int, float) or not math.isfinite(value)
                for value in (x, yaw, width))
                or sample.get("road_id") != site.get("original_road_id")
                or sample.get("lane_id") != site.get("original_lane_id")
                or abs(center[0] - x) > .75 or abs(center[1] - midpoint_y) > .35
                or abs(yaw) > 1.0 or width < 3
                or (previous_x is not None and x <= previous_x)):
            raise ValueError("original school lane route readback invalid")
        previous_x = x
    if site.get("school_designation_source") != "original Native school traffic-sign objects":
        raise ValueError("school designation provenance absent")
    if site.get("crossing_type") not in ("school_zone", "school_crossing_zone"):
        raise ValueError("school setting classification absent")
    return site


def footprint(vertices):
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError("missing original actor body")
    for vertex in vertices:
        if not isinstance(vertex, list) or len(vertex) < 3 or any(type(x) not in (int, float) or not math.isfinite(x) for x in vertex[:3]):
            raise ValueError("nonfinite original body vertex")
    return min(v[0] for v in vertices), min(v[1] for v in vertices), max(v[0] for v in vertices), max(v[1] for v in vertices)


def surface_gap(a, b):
    ax0, ay0, ax1, ay1 = footprint(a)
    bx0, by0, bx1, by1 = footprint(b)
    return math.hypot(max(bx0 - ax1, ax0 - bx1, 0), max(by0 - ay1, ay0 - by1, 0))


def observed_encounter(site, sample):
    if sample.get("pedestrian_class_source") is None or sample.get("driver_control_source") is None:
        raise ValueError("participant or driver source absent")
    if sample.get("pedestrian_class") != "pedestrian" or sample.get("ego_class") != "motor_vehicle":
        raise ValueError("wrong participant class")
    event = sample.get("driver_observation_event")
    if event is not None and (not isinstance(event, dict) or event.get("source") != "original_driver_input" or event.get("observed") is not True):
        raise ValueError("driver observation is not an original input event")
    ego, pedestrian = sample.get("ego_body_vertices_m"), sample.get("pedestrian_body_vertices_m")
    e, p = footprint(ego), footprint(pedestrian)
    markers = site["school_boundary_markers"][:2]
    start, end = sorted(m["location_xy_m"][0] for m in markers)
    if not (start <= p[0] and p[2] <= end):
        raise ValueError("pedestrian body outside original school markers")
    speed, brake = sample.get("ego_speed_mps"), sample.get("ego_brake")
    if type(speed) not in (int, float) or not math.isfinite(speed) or speed < 0:
        raise ValueError("original ego speed absent")
    if type(brake) not in (int, float) or not 0 <= brake <= 1:
        raise ValueError("original brake input absent")
    return {"surface_gap_m": surface_gap(ego, pedestrian),
            "longitudinal_gap_m": max(p[0] - e[2], 0),
            "pedestrian_within_original_school_markers": True,
            "school_marker_ids": [m["original_object_id"] for m in markers],
            "driver_observation_event": event, "ego_speed_mps": speed,
            "ego_brake": brake, "legal_proper_caution_verdict": None}


def controller(measurement, policy):
    """Compare engineering response timing, without a legal judgment."""
    if policy not in ("prompt_brake", "deferred_brake"):
        raise ValueError("unknown response policy")
    if not measurement.get("driver_observation_event"):
        return {"throttle": 0.25, "brake": 0.0, "steer": 0.0}
    brake = 1.0 if policy == "prompt_brake" or measurement["longitudinal_gap_m"] <= 2.0 else 0.0
    return {"throttle": 0.0 if brake else 0.25, "brake": brake, "steer": 0.0}

"""Independent source and saved-media audit for an school-setting pedestrian case."""
import argparse
import hashlib
import json
from pathlib import Path

from analysis import measure


ORIGINAL = ("encounter-history.jsonl", "school-site.json", "map.xodr",
            "trace.jsonl", "video_frames.jsonl", "acquisition.json")


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def rows(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def audit(attempt, processing, decode_receipt, case_id, media_verify=None):
    attempt, processing, decode_receipt = map(Path, (attempt, processing, decode_receipt))
    seal = read(attempt / "capture-seal.json")
    if seal.get("events") != ["capture_finished", "encoders_closed", "restoration_verified"]:
        raise ValueError("Native capture lifecycle incomplete")
    if not set(ORIGINAL) <= set(seal.get("sources", {})):
        raise ValueError("Native seal omits original school-setting pedestrian source")
    for name, digest in seal["sources"].items():
        if not (attempt / name).is_file() or sha(attempt / name) != digest:
            raise ValueError("sealed original missing or changed: " + name)
    native_exit = read(attempt / "native-exit.json")
    if native_exit.get("event") != "native_exit" or native_exit.get("capture_seal_sha256") != sha(attempt / "capture-seal.json"):
        raise ValueError("Native exit does not bind capture seal")
    owner = read(attempt / "owner-release.json")
    if owner.get("event") != "owner_released" or owner.get("operator_attested") is not True or owner.get("native_exit_sha256") != sha(attempt / "native-exit.json"):
        raise ValueError("Native owner release absent or stale")
    result = read(attempt / "result.json")
    if result.get("case_id") != case_id or not all(result.get(key) is True for key in
            ("setup_confirmed", "behavior_attempted", "maneuver_completed")):
        raise ValueError("physical completion not confirmed for exact case")
    acquisition = read(attempt / "acquisition.json")
    for name in ORIGINAL[:3]:
        info = acquisition.get(name, {})
        if info.get("kind") != "original_native" or info.get("sha256") != sha(attempt / name):
            raise ValueError("original road or pedestrian source absent: " + name)
    history, trace, mapping = (rows(attempt / name) for name in
                               ("encounter-history.jsonl", "trace.jsonl", "video_frames.jsonl"))
    if not history or not len(history) == len(trace) == len(mapping):
        raise ValueError("original encounter/frame streams incomplete")
    for index, (encounter, motion, frame) in enumerate(zip(history, trace, mapping)):
        ident = frame.get("carla_frame"), frame.get("time_s")
        if frame.get("video_frame") != index or any(
            (row.get("frame"), row.get("time_s")) != ident for row in (encounter, motion)
        ):
            raise ValueError("original encounter/frame identity join changed")
    value, _, _, site = measure(attempt)
    if value["first_observation"] is None:
        raise ValueError("original scripted-driver input event absent")
    if value["first_brake"] is None:
        raise ValueError("original motorist brake response absent")
    processed = read(processing)
    if (processed.get("format") != "worker-saved-processing" or
            processed.get("passed") is not True or processed.get("recorded_only") is not True):
        raise ValueError("saved-only processing receipt absent or failed")
    saved_result = Path(processed.get("result", ""))
    if not saved_result.is_file() or processed.get("result_sha256") != sha(saved_result) or read(saved_result).get("case_id") != case_id:
        raise ValueError("saved result missing, stale or wrong case")
    if media_verify is None:
        from worker_exchange.media import verify_receipt
        media_verify = verify_receipt
    video = Path(processed.get("analysis_directory", "")) / "raw.mkv"
    if not video.is_file():
        raise ValueError("saved primary video absent")
    media_verify(video, decode_receipt, len(mapping), mapping_sha256=sha(attempt / "video_frames.jsonl"))
    config = read(attempt / "config.json")
    scene = read(attempt / "scene.json")
    expected_policy = case_id.rsplit("__", 1)[-1]
    if scene.get("response_policy") != expected_policy or config.get("case", {}).get("response_policy") != expected_policy:
        raise ValueError("saved response policy differs from exact case")
    fixed_scene = {key: scene[key] for key in
                   ("ego_start_xy_m", "ego_end_xy_m", "pedestrian_start_xy_m",
                    "pedestrian_end_xy_m", "instrumented_observation_distance_m",
                    "pedestrian_target_speed_mps", "ego_spawn_offset_m", "duration_s", "rate_hz")}
    return {"format": "worker-delivery-audit", "passed": True, "case_id": case_id,
            "law_id": config["law_id"], "cell_id": config["cell_id"], "actor_id": config["actor"],
            "map_sha256": sha(attempt / "map.xodr"),
            "school_site_sha256": hashlib.sha256(json.dumps(site, sort_keys=True).encode()).hexdigest(),
            "fixed_scene_sha256": hashlib.sha256(json.dumps(fixed_scene, sort_keys=True).encode()).hexdigest(),
            "participant_classes": ["motor_vehicle", "pedestrian"],
            "camera_contract_sha256": hashlib.sha256(json.dumps(config["cameras"], sort_keys=True).encode()).hexdigest(),
            "duration_s": config["duration_s"], "response_policy": expected_policy,
            "measurement": value, "native_result_sha256": sha(attempt / "result.json"),
            "frame_count": len(mapping), "frame_map_sha256": sha(attempt / "video_frames.jsonl"),
            "video_sha256": sha(video), "source_decode_receipt_sha256": sha(decode_receipt),
            "human_observation_claimed": False, "legal_verdict": None}


def main():
    parser = argparse.ArgumentParser()
    for name in ("attempt", "processing", "decode-receipt", "case"):
        parser.add_argument("--" + name, required=True)
    args = parser.parse_args()
    print(json.dumps(audit(args.attempt, args.processing, args.decode_receipt, args.case), indent=2))


if __name__ == "__main__":
    main()

"""Independent paired audit of fixed conditions and measured response difference."""
import argparse
import json
from pathlib import Path


FIXED = ("law_id", "cell_id", "actor_id", "map_sha256", "school_site_sha256",
         "fixed_scene_sha256", "participant_classes", "camera_contract_sha256", "duration_s")


def audit(prompt, deferred):
    if (not prompt.get("case_id", "").endswith("__prompt_brake") or
            not deferred.get("case_id", "").endswith("__deferred_brake")):
        raise ValueError("wrong exact response comparison cases")
    for key in FIXED:
        if not prompt.get(key) or not deferred.get(key):
            raise ValueError("missing fixed condition: " + key)
        if prompt[key] != deferred[key]:
            raise ValueError("fixed condition differs: " + key)
    for record, policy in ((prompt, "prompt_brake"), (deferred, "deferred_brake")):
        if record.get("format") != "worker-delivery-audit" or record.get("passed") is not True:
            raise ValueError("source-audited delivery receipt missing")
        if record.get("response_policy") != policy:
            raise ValueError("declared response policy differs from exact case")
        if not all(record.get(key) for key in
                   ("native_result_sha256", "frame_map_sha256", "video_sha256", "source_decode_receipt_sha256")):
            raise ValueError("missing original saved-media binding")
        measurement = record.get("measurement", {})
        if measurement.get("format") != "worker-school-setting-pedestrian-measurements" or not all(
            measurement.get("sources", {}).get(name) for name in
            ("school-site.json", "map.xodr", "encounter-history.jsonl", "video_frames.jsonl")
        ):
            raise ValueError("missing source-bound pedestrian measurement")
        if measurement.get("frame_count") != record.get("frame_count") or measurement.get("first_observation") is None:
            raise ValueError("incomplete original observation/frame history")
        if measurement.get("legal_proper_caution_verdict") != "unresolved" or record.get("legal_verdict") is not None:
            raise ValueError("comparison asserted legal proper caution")
        if record.get("human_observation_claimed") is not False:
            raise ValueError("scripted input misrepresented as human cognition")
    first = prompt["measurement"].get("observed_response_delay_s")
    second = deferred["measurement"].get("observed_response_delay_s")
    if first is None or second is None or not first < second:
        raise ValueError("declared brake-response difference not physically observed")
    return {"comparison_id": "school_observation_response_timing", "passed": True,
            "fixed_conditions": list(FIXED),
            "difference": "original measured scripted-driver brake response delay",
            "prompt_response_delay_s": first, "deferred_response_delay_s": second,
            "human_observation_claimed": False, "legal_verdict": None}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("prompt")
    parser.add_argument("deferred")
    args = parser.parse_args()
    print(json.dumps(audit(json.loads(Path(args.prompt).read_text()),
                           json.loads(Path(args.deferred).read_text())), indent=2))


if __name__ == "__main__":
    main()
